def keep_existing_totals(apps, schema_editor):
    """Labour lines used qty as hours or days: keep it as days so qty = persons x days is unchanged.
    Overhead lines become a lump sum (qty 1) of their old amount."""
    for model, amount in (("EstimationLine", "amount"), ("BOQLine", "cost_amount")):
        M = apps.get_model("sales", model)
        M.objects.filter(category="labour").update(persons=1, days=models.F("qty"))
        for line in M.objects.filter(category="overhead").exclude(qty=1):
            line.unit_cost, line.qty, line.uom = getattr(line, amount), 1, "lot"
            if model == "BOQLine":
                line.selling_rate = line.selling_amount
            line.save()


